    record Decision(boolean retry, long delayMs, String reason) {
        static Decision retryAfter(long ms) { return new Decision(true, ms, "retry"); }
        static Decision stop(String reason) { return new Decision(false, 0, reason); }
    }

    static final Set<String> IDEMPOTENT = Set.of("GET", "HEAD", "OPTIONS", "PUT", "DELETE");
    static final Set<Integer> RETRYABLE = Set.of(429, 502, 503, 504);

