     * attempt = 1 for the first failure. jitter(maxMs) returns a value in [0, maxMs].
     * remainingMs = time left before the caller's deadline.
     */
    static Decision decide(Call call, Failure failure, int attempt, int maxAttempts, long remainingMs, LongUnaryOperator jitter) {
        boolean safeToRepeat = failure.kind().equals("connect-timeout") || IDEMPOTENT.contains(call.method()) || call.hasIdempotencyKey();
        if (!safeToRepeat) return Decision.stop("not idempotent");
        boolean worthRepeating = failure.kind().equals("connect-timeout") || failure.kind().equals("request-timeout") || RETRYABLE.contains(failure.status());
        if (!worthRepeating) return Decision.stop("not retryable");
        if (attempt >= maxAttempts) return Decision.stop("attempts exhausted");
        long delay;
        Long serverSays = retryAfterMs(failure.retryAfter());
        if (serverSays != null) {
            delay = Math.min(serverSays, 30_000);
        } else {
            long ceiling = Math.min(100L << (attempt - 1), 5_000);
            delay = jitter.applyAsLong(ceiling);
        }
        if (delay >= remainingMs) return Decision.stop("deadline");
        return Decision.retryAfter(delay);
    }

    static Long retryAfterMs(String header) {
        if (header == null || !header.matches("\\d{1,6}")) return null;
