            eq(decide(new Call("POST", false), Failure.connectTimeout(), 1, 4, 10_000, full), Decision.retryAfter(100));
        });
        test("4xx answers other than 429 are not retried", () -> {
            eq(List.of(decide(get, Failure.status(400), 1, 4, 10_000, full), decide(get, Failure.status(404), 1, 4, 10_000, full), decide(get, Failure.status(500), 1, 4, 10_000, full)),
