            eq(List.of(decide(get, Failure.status(429, "2"), 1, 4, 60_000, full), decide(get, Failure.status(503, "120"), 1, 4, 60_000, full), decide(get, Failure.status(503, "soon"), 1, 4, 60_000, full)),
