// ─────────────────────────────────────────────────────────────────────────
//  02 · timeouts from a deadline★★☆
//  concepts: HttpClient connectTimeout · HttpRequest.timeout · budget minus reserve · fail before sending
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.net.URI;
import java.net.http.*;
import java.time.*;
import java.util.*;

class Exercise {

    static final class DeadlineExceeded extends RuntimeException {
        DeadlineExceeded(String message) { super(message); }
    }

    static final Duration RESERVE = Duration.ofMillis(20);
    static final Duration MIN_USEFUL = Duration.ofMillis(50);

    /** A client that never waits for ever to connect and never follows redirects on its own. */
    static HttpClient client(Duration connectTimeout) {
        return HttpClient.newBuilder()
            .connectTimeout(connectTimeout)
            .followRedirects(HttpClient.Redirect.NEVER)
            .build();
    }

    /** A GET whose timeout fits inside the caller's deadline. */
    static HttpRequest prepare(URI uri, Instant deadline, Clock clock, Duration perCallCap) {
        Duration remaining = Duration.between(clock.instant(), deadline);
        Duration usable = remaining.minus(RESERVE);
        if (usable.compareTo(MIN_USEFUL) < 0) throw new DeadlineExceeded("only " + remaining.toMillis() + " ms left");
        Duration timeout = usable.compareTo(perCallCap) < 0 ? usable : perCallCap;
        return HttpRequest.newBuilder(uri)
            .GET()
            .timeout(timeout)
            .header("X-Deadline", deadline.toString())
            .build();
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        var now = Instant.parse("2026-03-07T10:00:00Z");
        var clock = Clock.fixed(now, ZoneOffset.UTC);
        var uri = URI.create("https://prices.internal/v1/sku/42");
        test("the client has a connect timeout and does not follow redirects", () -> {
            var c = client(Duration.ofSeconds(2));
            eq(List.of(c.connectTimeout(), c.followRedirects()), List.of(Optional.of(Duration.ofSeconds(2)), HttpClient.Redirect.NEVER));
        });
        test("plenty of budget: the per-call cap is the timeout", () -> {
            eq(prepare(uri, now.plusSeconds(10), clock, Duration.ofMillis(800)).timeout(), Optional.of(Duration.ofMillis(800)));
        });
        test("a tight budget: the timeout is what is left minus the reserve", () -> {
            eq(prepare(uri, now.plusMillis(300), clock, Duration.ofMillis(800)).timeout(), Optional.of(Duration.ofMillis(280)));
        });
        test("the deadline travels with the request", () -> {
            var r = prepare(uri, now.plusMillis(300), clock, Duration.ofMillis(800));
            eq(List.of(r.method(), r.uri(), r.headers().firstValue("X-Deadline")), List.of("GET", uri, Optional.of("2026-03-07T10:00:00.300Z")));
        });
        test("too little left: refuse before sending anything", () -> {
            raises(DeadlineExceeded.class, () -> prepare(uri, now.plusMillis(60), clock, Duration.ofMillis(800)), "only 60 ms left");
            raises(DeadlineExceeded.class, () -> prepare(uri, now.minusMillis(5), clock, Duration.ofMillis(800)));
        });
        test("exactly the minimum after the reserve is still allowed (boundary)", () -> {
            eq(prepare(uri, now.plusMillis(70), clock, Duration.ofMillis(800)).timeout(), Optional.of(Duration.ofMillis(50)));
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
