        if (!worthRepeating) return Decision.stop("not retryable");
        if (attempt >= maxAttempts) return Decision.stop("attempts exhausted");
        long delay;
        Long serverSays = retryAfterMs(failure.retryAfter());
        if (serverSays != null) {
            delay = Math.min(serverSays, 30_000);
        } else {
            long ceiling = Math.min(100L << (attempt - 1), 5_000);
            delay = jitter.applyAsLong(ceiling);
        }
        if (delay >= remainingMs) return Decision.stop("deadline");
        return Decision.retryAfter(delay);
    }

    static Long retryAfterMs(String header) {
        if (header == null || !header.matches("\\d{1,6}")) return null;
        return Long.parseLong(header) * 1000;
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        LongUnaryOperator full = max -> max;
        var get = new Call("GET", false);
        test("a 503 on a GET is retried after exponential backoff with jitter", () -> {
            eq(List.of(decide(get, Failure.status(503), 1, 4, 10_000, full), decide(get, Failure.status(503), 3, 4, 10_000, full), decide(get, Failure.status(503), 3, 4, 10_000, max -> max / 2)),
               List.of(Decision.retryAfter(100), Decision.retryAfter(400), Decision.retryAfter(200)));
        });
        test("a POST is not repeated unless it carries an idempotency key", () -> {
            eq(List.of(decide(new Call("POST", false), Failure.status(503), 1, 4, 10_000, full), decide(new Call("POST", true), Failure.status(503), 1, 4, 10_000, full)),
               List.of(Decision.stop("not idempotent"), Decision.retryAfter(100)));
        });
        test("a request timeout on a POST is not repeated: the server may have done it", () -> {
            eq(decide(new Call("POST", false), Failure.requestTimeout(), 1, 4, 10_000, full), Decision.stop("not idempotent"));
        });
        test("a connect timeout is safe to repeat for any method: nothing was sent", () -> {
            eq(decide(new Call("POST", false), Failure.connectTimeout(), 1, 4, 10_000, full), Decision.retryAfter(100));
        });
        test("4xx answers other than 429 are not retried", () -> {
            eq(List.of(decide(get, Failure.status(400), 1, 4, 10_000, full), decide(get, Failure.status(404), 1, 4, 10_000, full), decide(get, Failure.status(500), 1, 4, 10_000, full)),
               List.of(Decision.stop("not retryable"), Decision.stop("not retryable"), Decision.stop("not retryable")));
        });
        test("Retry-After in seconds wins over backoff, capped at 30 s", () -> {
            eq(List.of(decide(get, Failure.status(429, "2"), 1, 4, 60_000, full), decide(get, Failure.status(503, "120"), 1, 4, 60_000, full), decide(get, Failure.status(503, "soon"), 1, 4, 60_000, full)),
               List.of(Decision.retryAfter(2000), Decision.retryAfter(30_000), Decision.retryAfter(100)));
        });
        test("no retry past the last attempt or past the deadline (boundary)", () -> {
            eq(List.of(decide(get, Failure.status(503), 4, 4, 10_000, full), decide(get, Failure.status(503), 2, 4, 200, full), decide(get, Failure.status(503), 2, 4, 201, full), decide(get, Failure.status(503), 10, 20, 60_000, full)),
               List.of(Decision.stop("attempts exhausted"), Decision.stop("deadline"), Decision.retryAfter(200), Decision.retryAfter(5000)));
        });
        System.exit(report());
    }
